-- Nemesis Fire sprinkler report schema (shared Neon project, isolated schema).
-- Runtime credentials are provisioned through Neon control plane and stored outside source control.
-- This migration is additive and safe to rerun.

CREATE SCHEMA IF NOT EXISTS nemesis_fire AUTHORIZATION neondb_owner;

REVOKE ALL ON SCHEMA nemesis_fire FROM PUBLIC;

CREATE TABLE IF NOT EXISTS nemesis_fire.report_templates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), template_key text NOT NULL UNIQUE, title text NOT NULL, revision text NOT NULL, report_type text NOT NULL, source_document text NOT NULL, page_count smallint NOT NULL DEFAULT 4 CHECK (page_count > 0), active boolean NOT NULL DEFAULT true, field_schema jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE IF NOT EXISTS nemesis_fire.clients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_code text UNIQUE, business_name text NOT NULL, property_name text, address_line1 text NOT NULL, address_line2 text, city text NOT NULL, state char(2) NOT NULL DEFAULT 'CA', postal_code text, occupancy text, construction_type text, stories text, year_built text, contact_name text, contact_phone text, contact_email text, notes text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE IF NOT EXISTS nemesis_fire.sprinkler_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_number text NOT NULL UNIQUE, client_id uuid REFERENCES nemesis_fire.clients(id) ON DELETE RESTRICT, template_id uuid NOT NULL REFERENCES nemesis_fire.report_templates(id) ON DELETE RESTRICT, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','generated','finalized','void')), inspection_date date NOT NULL, system_type text NOT NULL CHECK (system_type IN ('Wet Pipe','Dry Pipe','Pre-action','Deluge','Other / not specified')), performed_by text, report_values jsonb NOT NULL DEFAULT '{}'::jsonb, revision integer NOT NULL DEFAULT 1 CHECK (revision > 0), created_by text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), generated_at timestamptz, finalized_at timestamptz);

CREATE INDEX IF NOT EXISTS sprinkler_reports_client_date_idx ON nemesis_fire.sprinkler_reports(client_id, inspection_date DESC);

CREATE TABLE IF NOT EXISTS nemesis_fire.report_template_items (template_id uuid NOT NULL REFERENCES nemesis_fire.report_templates(id) ON DELETE RESTRICT, item_key text NOT NULL, section text NOT NULL CHECK (section IN ('five-year','annual','maintenance')), item_number text NOT NULL, item_kind text NOT NULL CHECK (item_kind IN ('I','T','M')), description text NOT NULL, code_reference text NOT NULL, sort_order smallint NOT NULL, PRIMARY KEY(template_id,item_key), UNIQUE(template_id,sort_order));

CREATE TABLE IF NOT EXISTS nemesis_fire.report_risers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_id uuid NOT NULL REFERENCES nemesis_fire.sprinkler_reports(id) ON DELETE CASCADE, riser_number integer NOT NULL CHECK (riser_number > 0), location text, riser_diameter text, main_drain_diameter text, initial_static_pressure text, residual_pressure text, final_static_pressure text, result text CHECK (result IN ('pass','fail','na','')), comments text, UNIQUE (report_id, riser_number));

CREATE TABLE IF NOT EXISTS nemesis_fire.report_checklist_items (report_id uuid NOT NULL REFERENCES nemesis_fire.sprinkler_reports(id) ON DELETE CASCADE, item_key text NOT NULL, section text NOT NULL, item_number text NOT NULL, item_kind text NOT NULL CHECK (item_kind IN ('I','T','M')), description text NOT NULL, code_reference text, performed_on date, result text NOT NULL DEFAULT '' CHECK (result IN ('','pass','fail','na')), comment text NOT NULL DEFAULT '', PRIMARY KEY(report_id,item_key));

CREATE INDEX IF NOT EXISTS report_checklist_section_idx ON nemesis_fire.report_checklist_items(report_id,section,item_number);

CREATE TABLE IF NOT EXISTS nemesis_fire.report_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_id uuid NOT NULL REFERENCES nemesis_fire.sprinkler_reports(id) ON DELETE CASCADE, revision integer NOT NULL, document_service_job_id text, media_type text NOT NULL DEFAULT 'application/pdf' CHECK (media_type='application/pdf'), file_name text NOT NULL, sha256 char(64) NOT NULL, pdf_bytes bytea NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(report_id,revision));

CREATE TABLE IF NOT EXISTS nemesis_fire.report_audit_events (id bigserial PRIMARY KEY, report_id uuid NOT NULL REFERENCES nemesis_fire.sprinkler_reports(id) ON DELETE CASCADE, actor_id text, action text NOT NULL, details jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
















































GRANT USAGE ON SCHEMA nemesis_fire TO nemesis_fire_app, nemesis_fire_runtime;

GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA nemesis_fire TO nemesis_fire_app, nemesis_fire_runtime;

GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA nemesis_fire TO nemesis_fire_app, nemesis_fire_runtime;

ALTER DEFAULT PRIVILEGES FOR ROLE neondb_owner IN SCHEMA nemesis_fire GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO nemesis_fire_app, nemesis_fire_runtime;

ALTER DEFAULT PRIVILEGES FOR ROLE neondb_owner IN SCHEMA nemesis_fire GRANT USAGE, SELECT ON SEQUENCES TO nemesis_fire_app, nemesis_fire_runtime;
